0:1041.4,757.9 1:1143.8,1415.8 2:752.7,1048.7 3:1394.3,1105.1 4:1231.5,841.7 5:1308.0,917.3 6:1369.7,1289.0 7:1316.5,1358.2 8:938.6,1342.4 9:850.0,1260.7 10:792.7,855.8 11:858.5,792.4
"""

    private func observations() -> [FrameObservation] {
        Self.frames.split(separator: "\n", omittingEmptySubsequences: false).map { line in
            let detections = line.split(separator: " ").map { item -> ModelDetection in
                let parts = item.split(separator: ":")
                let xy = parts[1].split(separator: ",").map { Double($0)! }
                return ModelDetection(classIndex: Int(parts[0])!, point: SIMD2(xy[0], xy[1]), confidence: 0.8)
            }
            return FrameObservation(imageSize: CGSize(width: 2160, height: 3840), detections: detections)
        }
    }

    func testALockFormedFromPartOfTheBoardCorrectsItselfOnceTheBoardIsSeenWhole() throws {
        var tracker = MultiFrameTracker(ignoresDartsAtStart: false)
        let frames = observations()
        // The first lock, while the whole board is in view.
        for frame in frames.prefix(20) { _ = tracker.process(frame) }
        XCTAssertEqual(tracker.lastFrameUse, .usable(clearView: true))
        for frame in frames.dropFirst(20) { _ = tracker.process(frame) }
        // The last 50 frames see the whole (empty) board again.
        XCTAssertEqual(tracker.lastFrameUse, .usable(clearView: true), "the whole board is a clear view again")
        let h = try XCTUnwrap(tracker.homography)
        let points = try XCTUnwrap(frames.last).calibrationPoints
        XCTAssertEqual(points.count, 12)
        for (c, pixel) in points {
            XCTAssertLessThan(simd_distance(try XCTUnwrap(h.apply(pixel)), BoardCalibration.targetsMM[c]), 4, "point \(c)")
        }

        // The player steps in front again, long enough to lose the lock, and it forms again
        // from the lower half. Same camera pose as the corrected lock: the covered board is not
        // a clear view (darts may be behind the player).
        let size = CGSize(width: 2160, height: 3840)
        func view(_ classes: Set<Int>) -> FrameObservation {
            FrameObservation(imageSize: size, detections: points.filter { classes.contains($0.key) }.map {
                ModelDetection(classIndex: $0.key, point: $0.value, confidence: 0.8)
            })
        }
        for _ in 0..<DetectorTuning.lostFramesBeforeUnlock { _ = tracker.process(view([1])) }
        XCTAssertFalse(tracker.isLocked)
        for _ in 0..<12 { _ = tracker.process(view([1, 2, 6, 7, 8, 9])) }
        XCTAssertTrue(tracker.isLocked)
        XCTAssertEqual(tracker.lastFrameUse, .usable(clearView: false), "half the board is not a clear view")
    }
}
